inline std::string_view tariffPanelMessageKeyName(TariffPanelMessageKey key){
    static constexpr std::array<std::string_view,tariffPanelMessageKeyCount> names={{"tariff.panel.short_title","tariff.panel.short_resize","tariff.panel.short_keys","tariff.panel.footer_edit","tariff.panel.footer_review","tariff.panel.footer_browse","tariff.panel.offline_default","tariff.panel.editor_keys","tariff.panel.leave_title","tariff.panel.leave_keys","tariff.panel.remove_keys","tariff.panel.remove_preserve","tariff.panel.empty_table","tariff.panel.title","tariff.panel.unsaved_suffix","tariff.panel.fields_prompt","tariff.panel.fixed_suffix","tariff.panel.review_heading","tariff.panel.no_activation","tariff.panel.declared_forecast","tariff.panel.reset_limit","tariff.panel.excludes","tariff.panel.no_zero_fill","tariff.panel.full_cycle","tariff.panel.changes_heading","tariff.panel.no_changes","tariff.panel.confirmation_only"}};
    const auto index=static_cast<std::size_t>(key);return index<names.size()?names[index]:std::string_view{};
}
inline LocalizedMessage tariffPanelMessage(std::string_view language,TariffPanelMessageKey key){
    const auto index=static_cast<std::size_t>(key);if(index>=tariffPanelMessageKeyCount)return {};
    const auto &source=tariffPanelLocalePacks()[0];const auto *selected=&source;for(const auto &pack:tariffPanelLocalePacks())if(pack.id==language){selected=&pack;break;}
    if(selected->id!=language||!validTemplateTranslation(source.messages[index],selected->messages[index]))return {source.messages[index],source.id,source.review,true,false};
    return {selected->messages[index],selected->id,selected->review,false,selected->rtl};
}
inline std::string tariffPanelEnglish(TariffPanelMessageKey key){return std::string(tariffPanelMessage("en",key).text);}
